import {deliveryFee} from './delivery.js';
import {SUPABASE_URL,SUPABASE_KEY} from './supabase-config.js';
import {discountPercent,discountedPrice} from './pricing.js';
import {escapeHTML,safeImage} from './catalog.js';
const $=s=>document.querySelector(s);
const message=text=>{$('#message').textContent=text;};
let db,products=[],photoItems=[],busy=false,discountsReady=false,imagesReady=false,deliveryReady=false,recovering=location.hash.includes('type=recovery');
const editor=$('#product-dialog'),form=$('#product-form');
function setBusy(value){busy=value;form.querySelectorAll('button').forEach(b=>b.disabled=value);$('#save-product').textContent=value?'Saving…':'Save product';}
async function authorized(){const {data:{user},error}=await db.auth.getUser();if(error||!user)return false;const result=await db.from('miroku_admins').select('user_id').eq('user_id',user.id).maybeSingle();if(result.error)throw new Error('Database setup is incomplete. Follow the Supabase setup guide in the repository.');return !!result.data;}
async function showWorkspace(){try{if(!await authorized()){await db.auth.signOut();message('This account does not have store admin access.');return;}$('#login-panel').hidden=true;$('#password-panel').hidden=true;$('#workspace').hidden=false;message('');if(new URLSearchParams(location.search).get('next')==='orders'){location.replace('/admin/orders');return;}await refresh();}catch(e){message(e.message);}}
async function refresh(){const {data,error}=await db.from('miroku_products').select('*').order('created_at',{ascending:false});if(error)throw new Error('Could not load products. Check the database setup and try Refresh.');products=data;const deliveryProbe=await db.from('miroku_products').select('delivery_fee').limit(1);deliveryReady=!deliveryProbe.error;form.elements.delivery_mode.disabled=!deliveryReady;form.elements.delivery_cost.disabled=!deliveryReady;const imageProbe=await db.from('miroku_products').select('images').limit(1);imagesReady=!imageProbe.error;const probe=await db.from('miroku_products').select('compare_at_price').limit(1);discountsReady=!probe.error;form.elements.compare_at_price.disabled=!discountsReady;form.elements.discount.disabled=!discountsReady;render();if(!deliveryReady)message('Delivery settings need the one-time database update: supabase/add-delivery.sql.');else if(!imagesReady)message('Multiple photos need the one-time database update: supabase/add-product-images.sql.');else if(!discountsReady)message('Original prices and discounts need the one-time database update. See supabase/add-discounts.sql in the repository.');}
function render(){const currency=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(n);$('#product-count').textContent=`${products.length} product${products.length===1?'':'s'} · ${products.filter(p=>p.published).length} published`;$('#product-list').innerHTML=products.length?products.map(p=>`<article class="admin-product"><img src="${escapeHTML(safeImage(p.image))}" alt="${escapeHTML(p.name)}"><span class="status-label">${p.published?'Published':'Draft'}</span><h2>${escapeHTML(p.name)}</h2><p>${currency(p.price)} ${Number(p.compare_at_price)>Number(p.price)?`<del>${currency(p.compare_at_price)}</del> <span class="discount-label">${discountPercent(p.price,p.compare_at_price)}% off</span>`:''} · ${p.stock} in stock</p><p>${escapeHTML(p.category)}</p><div class="actions"><button class="secondary" data-edit="${p.id}">Edit</button><button class="text-button" data-toggle="${p.id}">${p.published?'Unpublish':'Publish'}</button>${!p.published?`<button class="text-button danger" data-delete="${p.id}">Delete draft</button>`:''}</div></article>`).join(''):'<div class="empty-admin"><h2>Your collection starts here.</h2><p>Add your first product, upload a photo, and publish when it is ready.</p></div>';}
function closeEditor(){if(busy)return;editor.close();clearPhotoItems();}
function openEditor(p){form.reset();$('#editor-message').textContent='';clearPhotoItems();photoItems=(Array.isArray(p?.images)&&p.images.length?p.images:p?.image?[p.image]:[]).filter(safeImage).map(url=>({url}));for(const key of ['id','name','category','price','compare_at_price','stock','color','tag','description'])form.elements[key].value=p?.[key]??(key==='stock'?0:'');form.elements.discount.value=discountPercent(p?.price,p?.compare_at_price)||'';form.elements.delivery_mode.value=p?(p.delivery_fee==null?'unset':Number(p.delivery_fee)===0?'free':'paid'):'free';form.elements.delivery_cost.value=p?.delivery_fee>0?p.delivery_fee:'';updateDeliveryFields();form.elements.published.checked=!!p?.published;$('#editor-title').textContent=p?'Edit product':'Add product';renderPhotoPreviews();editor.showModal();}
async function compressPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Choose a JPEG, PNG or WebP photo smaller than 10 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.85));if(!blob||blob.size>5*1024*1024)throw new Error('Photo could not be resized. Try a smaller photo.');return blob;}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const login=e.currentTarget;const b=login.querySelector('button');b.disabled=true;try{const {error}=await db.auth.signInWithPassword({email:login.email.value.trim(),password:login.password.value});if(error){if(error.code==='email_not_confirmed')throw new Error('Confirm your email in Supabase Authentication before signing in.');if(error.code==='invalid_credentials')throw new Error('Email or password is incorrect for the connected Supabase project.');if(error.name==='AuthRetryableFetchError'||!error.status||error.status>=500)throw new Error('Cannot reach the Supabase project. Check that the project is active and its URL is correct.');throw new Error('Sign-in could not complete: '+error.message);}login.password.value='';await showWorkspace();}catch(err){message(err.message);}finally{b.disabled=false;}});
$('#reset-password').addEventListener('click',async()=>{const email=$('#login-form').email.value.trim();if(!email){message('Enter your email first.');return;}const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}/admin`});message(error?'Could not send the reset link. Please try again.':'If this account exists, a password reset link will be sent to your email.');});
$('#password-form').addEventListener('submit',async e=>{e.preventDefault();const passwordForm=e.currentTarget;const b=passwordForm.querySelector('button');b.disabled=true;const {error}=await db.auth.updateUser({password:passwordForm.password.value});b.disabled=false;if(error){message('Could not update your password. Request a new reset link.');return;}passwordForm.reset();recovering=false;await showWorkspace();});
$('#sign-out').addEventListener('click',async()=>{const {error}=await db.auth.signOut();if(error){message('Could not sign out. Please try again.');return;}products=[];$('#workspace').hidden=true;$('#product-list').replaceChildren();$('#login-panel').hidden=false;message('Signed out.');});
$('#refresh').addEventListener('click',()=>refresh().catch(e=>message(e.message)));$('#new-product').addEventListener('click',()=>openEditor());$('#close-editor').addEventListener('click',closeEditor);$('#cancel-editor').addEventListener('click',closeEditor);editor.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;setBusy(true);let uploadedPaths=[];try{if(!await authorized())throw new Error('Your session expired. Sign in again.');const id=form.elements.id.value||crypto.randomUUID();const fields=new FormData(form);const compare=fields.get('compare_at_price')?Number(fields.get('compare_at_price')):null;const price=Number(fields.get('price')),stock=Number(fields.get('stock'));if(!Number.isFinite(price)||price<=0||price>10000000||!Number.isInteger(stock)||stock<0||stock>1000000)throw new Error('Enter a valid price and whole-number stock quantity.');if(compare!==null&&(!Number.isFinite(compare)||compare<price||compare>10000000))throw new Error('Original price must be at least the selling price.');if(!photoItems.length)throw new Error('Add at least one product photo.');if(photoItems.length>4)throw new Error('Choose up to four photos.');if(!imagesReady&&photoItems.length>1)throw new Error('Run the multiple-photo database update before saving more than one photo.');const images=[];for(const item of photoItems){if(item.file){const blob=await compressPhoto(item.file);const path=`${id}/${crypto.randomUUID()}.webp`;const {error}=await db.storage.from('miroku-product-images').upload(path,blob,{contentType:'image/webp',upsert:false});if(error)throw new Error('Photo upload failed. Your product has not been changed.');uploadedPaths.push(path);images.push(db.storage.from('miroku-product-images').getPublicUrl(path).data.publicUrl);}else{if(!safeImage(item.url))throw new Error('Invalid product photo.');images.push(item.url);}}const image=images[0];const record={id,name:fields.get('name').trim(),category:fields.get('category').trim(),description:fields.get('description').trim(),color:fields.get('color').trim(),tag:fields.get('tag').trim(),price,stock,image,published:form.elements.published.checked};if(deliveryReady)record.delivery_fee=deliveryFee(form.elements.delivery_mode.value,form.elements.delivery_cost.value);if(imagesReady)record.images=images;if(discountsReady)record.compare_at_price=compare;if(!record.name||!record.category||!record.description)throw new Error('Name, category and description cannot be blank.');const result=form.elements.id.value?await db.from('miroku_products').update(record).eq('id',id).select('id').single():await db.from('miroku_products').insert(record).select('id').single();if(result.error)throw new Error('Product was not saved. Check your connection and admin permissions.');uploadedPaths=[];setBusy(false);closeEditor();message('Product saved. Published changes appear in the store on refresh.');await refresh();}catch(err){if(uploadedPaths.length)await db.storage.from('miroku-product-images').remove(uploadedPaths);$('#editor-message').textContent=err.message;}finally{setBusy(false);}});
$('#product-list').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const p=products.find(p=>p.id===(b.dataset.edit||b.dataset.toggle||b.dataset.delete));if(!p)return;if(b.dataset.edit){openEditor(p);return;}if(b.dataset.delete){if(p.published)return;if(!confirm('Permanently delete the draft "'+p.name+'"? This cannot be undone.'))return;b.disabled=true;try{const {data,error}=await db.from('miroku_products').delete().eq('id',p.id).eq('published',false).select('id');if(error||!data?.length)throw new Error('Draft was not deleted. It may have been published or your session expired.');await refresh();message('Draft deleted.');}catch(err){message(err.message);}finally{b.disabled=false;}return;}b.disabled=true;try{const {data,error}=await db.from('miroku_products').update({published:!p.published}).eq('id',p.id).select('id').single();if(error||!data)throw new Error('Could not change publication status. Sign in again and retry.');await refresh();message(p.published?'Product unpublished.':'Product published.');}catch(err){message(err.message);}finally{b.disabled=false;}});
try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');db=createClient(SUPABASE_URL,SUPABASE_KEY);$('#login-form button').disabled=false;$('#reset-password').disabled=false;db.auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY'){recovering=true;$('#login-panel').hidden=true;$('#workspace').hidden=true;$('#password-panel').hidden=false;}if(event==='SIGNED_OUT'){products=[];$('#workspace').hidden=true;$('#password-panel').hidden=true;$('#login-panel').hidden=false;}});const {data:{session}}=await db.auth.getSession();if(recovering){$('#login-panel').hidden=true;$('#password-panel').hidden=false;}else if(session)await showWorkspace();}catch{message('Could not connect to the admin service. Please refresh and try again.');$('#login-form button').disabled=true;$('#reset-password').disabled=true;}

form.elements.discount.addEventListener('input',()=>{try{form.elements.price.value=discountedPrice(form.elements.compare_at_price.value,form.elements.discount.value);$('#editor-message').textContent='';}catch(e){$('#editor-message').textContent=e.message;}});
form.elements.price.addEventListener('input',()=>{form.elements.discount.value=discountPercent(form.elements.price.value,form.elements.compare_at_price.value)||'';});
form.elements.compare_at_price.addEventListener('input',()=>{form.elements.discount.value=discountPercent(form.elements.price.value,form.elements.compare_at_price.value)||'';});

function clearPhotoItems(){for(const item of photoItems)if(item.file)URL.revokeObjectURL(item.url);photoItems=[];}
function renderPhotoPreviews(){const container=$('#photo-previews');container.replaceChildren();photoItems.forEach((item,index)=>{const tile=document.createElement('div');tile.className='photo-tile';const img=document.createElement('img');img.src=item.url;img.alt='Product photo '+(index+1);tile.append(img);const label=document.createElement('span');label.textContent=index===0?'Cover photo':'Photo '+(index+1);tile.append(label);if(index>0){const cover=document.createElement('button');cover.type='button';cover.className='text-button';cover.textContent='Make cover';cover.disabled=busy;cover.addEventListener('click',()=>{photoItems.unshift(photoItems.splice(index,1)[0]);renderPhotoPreviews();});tile.append(cover);}const remove=document.createElement('button');remove.type='button';remove.className='text-button danger';remove.textContent='Remove';remove.disabled=busy;remove.addEventListener('click',()=>{const [removed]=photoItems.splice(index,1);if(removed.file)URL.revokeObjectURL(removed.url);renderPhotoPreviews();});tile.append(remove);container.append(tile);});}
form.elements.photo.addEventListener('change',()=>{if(busy){form.elements.photo.value='';return;}const files=[...form.elements.photo.files];form.elements.photo.value='';if(photoItems.length+files.length>4){$('#editor-message').textContent='You can add up to four photos. Remove a photo first to replace it.';return;}if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)){$('#editor-message').textContent='Choose JPEG, PNG or WebP photos smaller than 10 MB each.';return;}photoItems.push(...files.map(file=>({file,url:URL.createObjectURL(file)})));$('#editor-message').textContent='';renderPhotoPreviews();});

function updateDeliveryFields(){const paid=form.elements.delivery_mode.value==='paid';$('#delivery-cost-label').hidden=!paid;form.elements.delivery_cost.required=paid&&deliveryReady;}
form.elements.delivery_mode.addEventListener('change',updateDeliveryFields);
